/// The element of type `name`, if the catalog lists it.
pub fn element(name: &str) -> Option<&'static Element> {
    ELEMENTS.iter().find(|e| e.name == name)
}

/// The embed kind `kind`, if the catalog lists it.
pub fn embed(kind: &str) -> Option<&'static Embed> {
    EMBEDS.iter().find(|e| e.kind == kind)
}

/// The material kind `kind`, if the catalog lists it.
pub fn material_kind(kind: &str) -> Option<&'static MaterialKind> {
    MATERIAL_KINDS.iter().find(|k| k.kind == kind)
}
